INSERT INTO "public"."calitate_content" ("id", "section_key", "image_url", "title", "description", "label", "created_at") VALUES
	('9120c8ec-67c0-4e63-b507-3279f2953bb0', 'hero', '/images/banners/calitate_hero.png', 'Calitate & Ingrediente', 'Nu facem compromisuri când vine vorba de sănătatea ta. Selectăm doar materie primă de grad farmaceutic.', NULL, '2026-08-05 16:20:20.100171+00'),
	('649fc407-af79-4e36-a0bb-d3e0d2ebcc10', 'card_1', '/images/banners/calitate_proces.png', 'Extracte Standardizate', 'Nu folosim pulberi de plante simple, ci extracte standardizate, asigurând exact cantitatea de substanță activă de care corpul are nevoie.', 'Eficiență', '2026-08-05 16:20:20.100171+00'),
	('c3c0404a-5b7f-476a-b4c0-c49546024c69', 'card_2', '/images/banners/calitate_surse.png', 'Tehnologie Lipozomală', 'Încapsulăm nutrienții sensibili în sfere lipidice (lipozomi) pentru a-i proteja de acidul gastric și a le crește rata de absorbție.', 'Absorbție', '2026-08-05 16:20:20.100171+00'),
	('0ac62375-0f4f-441d-bacb-6322c0ffc3af', 'card_3', '/images/zen_stones.png', 'Curat & Vegan', 'Capsulele noastre sunt 100% vegetale. Excludem coloranții, aromele artificiale, glutenul sau conservanții toxici din toate formulele.', 'Puritate', '2026-08-05 16:20:20.100171+00'),
	('8b7b1c41-b3db-466b-892b-9220931f9f46', 'simple_section', '/images/banners/calitate_ingrediente.png', 'Știința purității absolute', 'Eficiența oricărui supliment depinde de calitatea materiei prime. Din acest motiv, la Longevity Pharma lucrăm exclusiv cu furnizori certificați și verificăm riguros fiecare lot de ingrediente.', NULL, '2026-08-05 16:20:20.100171+00');
