INSERT INTO "public"."journal_articles" ("id", "title", "slug", "summary", "content", "image_url", "author", "tags", "published_at") VALUES
	('52ec529d-9129-40e8-8e8f-114c69c94eb5', 'Cum funcționează NMN-ul la nivel celular pentru a întârzia îmbătrânirea', 'cum-functioneaza-nmn-ul-la-nivel-celular', 'Nicotinamida mononucleotidă (NMN) a captat atenția lumii științifice. Află cum restabilește nivelurile de NAD+ și influențează direct longevitatea.', 'NAD+ (Nicotinamida Adenin Dinucleotida) este o coenzimă esențială prezentă în fiecare celulă vie, responsabilă pentru producția de energie și repararea ADN-ului. Odată cu înaintarea în vârstă, nivelurile de NAD+ scad dramatic, declanșând procesele de îmbătrânire celulară.
