	('f4a827c1-7d94-4bc1-8e92-7b72399e3456', '520bb666-e4f9-4dcd-836e-1c4f0a51d8f7', 'Olive Leaf Extract', 'olive-leaf', 55.00, '/images/premium_bottle_8-removebg-preview.png', false, '2026-08-05 13:19:30.945511+00', false, false, false, false, 'extracte', 'Antiviral și suport cardiovascular.', 4.70, 95, '{}', true, '{"faq": [{"answer": "Recomandăm administrarea conform instrucțiunilor de pe ambalaj, de preferat în timpul meselor pentru o absorbție optimă.", "question": "Cum se administrează Olive Leaf Extract?"}, {"answer": "Da, Olive Leaf Extract folosește ingrediente premium și extracte standardizate de cea mai înaltă puritate.", "question": "Este acest produs natural?"}], "reviews": [{"date": "12 August 2026", "author": "Andrei M.", "rating": 5, "comment": "Un produs excelent, se simte calitatea din primele zile de utilizare. Recomand Olive Leaf Extract!"}, {"date": "05 August 2026", "author": "Elena P.", "rating": 5, "comment": "Foarte mulțumită de rezultate. Livrare rapidă și produs conform descrierii."}], "banner_text": "Calitate superioară și eficiență maximă pentru corpul tău.", "content_image": "/images/premium_bottle_8-removebg-preview.png", "why_recommend": ["Ingrediente 100% pure și atent selecționate", "Fără aditivi inutili sau conservanți artificiali", "Absorbție superioară datorită formulei avansate"], "ingredients_table": [{"vnr": "**", "name": "Extract purificat standardizat", "quantity": "500 mg"}, {"vnr": "15%", "name": "Complex de suport asimilare", "quantity": "50 mg"}, {"vnr": "**", "name": "Capsulă vegetală V-Caps®", "quantity": "100 mg"}], "intro_description": "<p>Descoperă beneficiile extraordinare oferite de <strong>Olive Leaf Extract</strong>. Formulă dezvoltată special pentru a susține performanța optimă a organismului tău zi de zi.</p><p>Prin combinarea extractelor de înaltă puritate, acest supliment reprezintă alegerea perfectă pentru un stil de viață echilibrat și sănătos.</p>"}', 'PureScience'),
	('73ffa516-a754-43c0-945e-ecb471bc9e3c', 'cc54dd04-bba1-425d-9abc-1f8d95692a08', 'Astaxantină Naturală 12mg', 'astaxantina', 95.00, '/images/premium_bottle_10-removebg-preview.png', false, '2026-08-05 13:19:30.945511+00', true, false, false, false, 'antioxidanti', 'Regele carotenoidelor pentru ochi și piele.', 4.80, 190, '{Bestseller}', true, '{"faq": [{"answer": "Recomandăm administrarea conform instrucțiunilor de pe ambalaj, de preferat în timpul meselor pentru o absorbție optimă.", "question": "Cum se administrează Astaxantină Naturală 12mg?"}, {"answer": "Da, Astaxantină Naturală 12mg folosește ingrediente premium și extracte standardizate de cea mai înaltă puritate.", "question": "Este acest produs natural?"}], "reviews": [{"date": "12 August 2026", "author": "Andrei M.", "rating": 5, "comment": "Un produs excelent, se simte calitatea din primele zile de utilizare. Recomand Astaxantină Naturală 12mg!"}, {"date": "05 August 2026", "author": "Elena P.", "rating": 5, "comment": "Foarte mulțumită de rezultate. Livrare rapidă și produs conform descrierii."}], "banner_text": "Calitate superioară și eficiență maximă pentru corpul tău.", "content_image": "/images/premium_bottle_10-removebg-preview.png", "why_recommend": ["Ingrediente 100% pure și atent selecționate", "Fără aditivi inutili sau conservanți artificiali", "Absorbție superioară datorită formulei avansate"], "ingredients_table": [{"vnr": "**", "name": "Extract purificat standardizat", "quantity": "500 mg"}, {"vnr": "15%", "name": "Complex de suport asimilare", "quantity": "50 mg"}, {"vnr": "**", "name": "Capsulă vegetală V-Caps®", "quantity": "100 mg"}], "intro_description": "<p>Descoperă beneficiile extraordinare oferite de <strong>Astaxantină Naturală 12mg</strong>. Formulă dezvoltată special pentru a susține performanța optimă a organismului tău zi de zi.</p><p>Prin combinarea extractelor de înaltă puritate, acest supliment reprezintă alegerea perfectă pentru un stil de viață echilibrat și sănătos.</p>"}', 'NovaBio'),
	('af2c0aa0-9a25-4e8b-a003-70876b266cc7', NULL, 'NMN Pur 500mg - Anti-Aging', 'nmn-pur-500mg', 189.99, '/images/longevitate3.png', false, '2026-08-04 11:54:49.568821+00', true, false, false, true, 'longevitate', 'Precursor direct al NAD+, formulat pentru o absorbție intracelulară maximă. Susține repararea ADN-ului și crește nivelul de energie celulară.', 4.90, 124, '{Bestseller}', true, '{"faq": [{"answer": "Pentru rezultate optime, recomandăm administrarea a 1-2 capsule de NMN dimineața, pe stomacul gol, cu un pahar cu apă. NMN-ul este o moleculă care oferă energie, motiv pentru care nu este recomandat să fie luat seara târziu, putând afecta calitatea somnului.", "question": "Când și cum se administrează NMN-ul?"}, {"answer": "Majoritatea utilizatorilor raportează o creștere a nivelului de energie și o claritate mentală mai bună în primele 7-10 zile de administrare constantă. Efectele profunde anti-aging la nivel celular se consolidează după 2-3 luni de utilizare regulată.", "question": "În cât timp voi vedea primele rezultate?"}, {"answer": "Nu. Formula noastră este sintetizată printr-un proces enzimatic avansat și este stabilizată termic. Produsul poate fi păstrat la temperatura camerei, într-un loc uscat și ferit de razele directe ale soarelui, menținându-și puritatea de >99%.", "question": "NMN-ul vostru are nevoie de păstrare la frigider?"}], "reviews": [{"date": "12 Iunie 2026", "author": "Mihai V.", "rating": 5, "comment": "Am început să iau de 3 săptămâni. Cel mai evident efect este că nu mai am acea cădere de energie de la ora 15:00. Mă simt mult mai alert la birou și parcă mă recuperez mai repede după sală."}, {"date": "03 Mai 2026", "author": "Elena D.", "rating": 5, "comment": "Folosesc NMN în combinație cu resveratrol și rezultatele sunt excelente. Capsulele nu au un gust neplăcut și se înghit ușor. Apreciez enorm că oferiți certificatul de analiză a purității!"}, {"date": "18 Aprilie 2026", "author": "Radu S.", "rating": 4, "comment": "Produs foarte bun, calitativ. Singurul minus este că o singură dată s-a întârziat livrarea cu o zi, dar în rest, produsul face exact ce promite: energie curată toată ziua."}], "banner_text": "Refă-ți rezervele de energie la nivel celular cu molecula longevității!", "content_image": "/longevitate3.png", "why_recommend": ["Puritate testată independent > 99%", "Formulă stabilizată la temperatură, fără necesitate de refrigerare", "Absorbție maximă datorită capsulelor gastro-rezistente", "Nu conține metale grele, gluten sau OMG-uri"], "ingredients_table": [{"vnr": "**", "name": "B-Nicotinamid Mononucleotid (NMN)", "quantity": "500 mg"}, {"vnr": "**", "name": "Extract de Piper Negru (Bioperină)", "quantity": "5 mg"}, {"vnr": "**", "name": "Capsulă vegetală (HPMC)", "quantity": "120 mg"}, {"vnr": "**", "name": "Făină de orez organică (Agent de încărcare)", "quantity": "45 mg"}, {"vnr": "**", "name": "L-Leucină (Lubrifiant natural)", "quantity": "10 mg"}], "intro_description": "<p><strong>NMN (Nicotinamid Mononucleotid)</strong> este molecula care a revoluționat domeniul anti-aging. Funcționează ca un precursor direct al NAD+ (Nicotinamidă Adenin Dinucleotidă), o coenzimă vitală prezentă în fiecare celulă a corpului nostru.</p><p>Pe măsură ce îmbătrânim, nivelurile de NAD+ scad dramatic, ceea ce duce la oboseală, declin cognitiv și încetinirea metabolismului. Prin suplimentarea zilnică cu NMN de puritate 99%, susții refacerea celulară și energia din interior spre exterior.</p>"}', NULL),
	('0c9fd816-e8c7-4b2f-a6ac-cc508eb11cc3', NULL, 'Urolitină A 500mg Extract', 'spermidina-extract', 180.00, '/images/longevitate4.png', false, '2026-08-04 09:46:15.360648+00', true, false, false, true, 'longevitate', 'Extracție naturală pură ce declanșează autofagia – procesul prin care corpul își reciclează celulele îmbătrânite sau deteriorate. Secretul celular pentru o viață lungă și vitală.', 4.80, 62, NULL, true, '{"faq": [{"answer": "Recomandăm 1-2 capsule pe zi, dimineața cu un pahar de apă, pentru a maximiza rata de absorbție celulară de-a lungul zilei.", "question": "Care este doza recomandată?"}, {"answer": "Efectele de creștere a energiei se simt în 7-14 zile, însă refacerea celulară profundă necesită o cură de minimum 3 luni pentru rezultate optime.", "question": "În cât timp voi vedea efectele anti-aging?"}, {"answer": "Da, substanțele active sunt 100% bio-identice cu moleculele produse deja de corpul uman, fiind complet sigure și non-toxice.", "question": "Este sigur de administrat pe termen lung?"}], "reviews": [{"date": "10 Iulie 2026", "author": "Valeriu M.", "rating": 5, "comment": "Folosesc de 2 luni și am observat o îmbunătățire drastică a rezistenței la efort. Nu mai obosesc la fel de repede."}, {"date": "22 Iunie 2026", "author": "Simona T.", "rating": 5, "comment": "Analizele mele de sânge s-au îmbunătățit de când folosesc produsele voastre de longevitate. Recomand cu drag!"}, {"date": "05 Mai 2026", "author": "Andrei G.", "rating": 4, "comment": "Un supliment foarte bun. Prețul este corect pentru calitatea oferită."}], "banner_text": "Activează reînnoirea celulară și trăiește la potențialul maxim!", "content_image": "/longevitate4.png", "why_recommend": ["Puritate testată independent > 99%", "Formulă stabilizată pentru biodisponibilitate maximă", "Fără efecte adverse, sigur pentru utilizare zilnică", "Combate stresul oxidativ de la prima administrare"], "ingredients_table": [{"vnr": "**", "name": "Extract Purificat (99%)", "quantity": "400 mg"}, {"vnr": "**", "name": "Complex de absorbție lipozomal", "quantity": "50 mg"}, {"vnr": "**", "name": "Capsulă vegetală (HPMC)", "quantity": "110 mg"}, {"vnr": "**", "name": "Celuloză microcristalină", "quantity": "30 mg"}, {"vnr": "**", "name": "Stearat de magneziu vegetal", "quantity": "5 mg"}], "intro_description": "<p>Formulă de ultimă generație concepută pentru a încetini procesul de îmbătrânire celulară. Acționând direct la nivelul mitocondriilor, acest supliment stimulează longevitatea și vitalitatea din interior spre exterior.</p><p>Prin activarea procesului natural de autofagie (curățarea celulelor senescente), corpul tău își recapătă energia și capacitatea de regenerare specifice tinereții.</p>"}', NULL),
	('bb8181ab-19ea-4f30-a29c-2d77c0b1e134', NULL, 'Omega-3 Ulei de Pește Sălbatic', 'omega-3-sălbatic', 110.00, '/images/longevitate1.png', false, '2026-08-04 09:46:15.360648+00', true, false, false, true, 'esentiale', 'Sursă pură, sustenabilă, de omega-3 din pește sălbatic (fără metale grele). Susține funcția cognitivă și lubrifierea articulațiilor.', 4.80, 175, NULL, true, '{"faq": [{"answer": "Deși extractele noastre sunt foarte blânde cu mucoasa gastrică, recomandăm administrarea după masă (preferabil o masă ce conține puține grăsimi sănătoase).", "question": "Se poate lua pe stomacul gol?"}, {"answer": "Da, acest produs face parte din categoria Esențialelor, așadar corpul are nevoie constantă de el pentru a preveni carențele.", "question": "Pot folosi produsul pe tot parcursul anului?"}], "reviews": [{"date": "14 August 2026", "author": "Camelia P.", "rating": 5, "comment": "Mă simt excelent de când îl iau, iar cel mai mare plus este că nu îmi provoacă absolut deloc greață, cum pățeam la alte branduri."}, {"date": "29 Iulie 2026", "author": "Florin B.", "rating": 5, "comment": "Analizele au ieșit perfect! Fix ce căutam."}], "banner_text": "Fundația unei sănătăți de fier în fiecare zi!", "content_image": "/longevitate1.png", "why_recommend": ["Formă moleculară bio-identică pentru asimilare perfectă", "Fără metale grele sau toxine", "Necesar zilnic pentru o funcționare optimă a corpului"], "ingredients_table": [{"vnr": "100%", "name": "Substanță Activă Premium", "quantity": "1000 mg"}, {"vnr": "**", "name": "Cofactori de absorbție", "quantity": "25 mg"}, {"vnr": "**", "name": "Fosfat dicalcic", "quantity": "40 mg"}, {"vnr": "**", "name": "Înveliș enteric", "quantity": "15 mg"}, {"vnr": "**", "name": "Dioxid de siliciu", "quantity": "2 mg"}], "intro_description": "<p>Fundația sănătății tale zilnice. Corpul nostru nu poate sintetiza eficient anumite micro-elemente, de aceea un supliment curat și extrem de asimilabil face toată diferența.</p><p>Fie că vorbim de susținerea imunității, protecția cardiovasculară sau sănătatea oaselor, acest produs de bază a fost formulat folosind doar cele mai calitative și sigure materii prime.</p>"}', NULL),
