	('7befa0fc-f3b9-4dac-849f-ee69de15b96c', NULL, 'Colagen Peptide + Acid Hialuronic', 'colagen-peptide', 165.00, '/images/premium_bottle_2-removebg-preview.png', false, '2026-08-04 11:54:49.568821+00', true, false, false, false, 'longevitate', 'Formula supremă pentru piele și articulații. Peptidele de colagen redau elasticitatea țesuturilor și hidratează structura dermului.', 4.90, 312, '{"Pentru Femei"}', true, '{"faq": [{"answer": "Recomandăm 1-2 capsule pe zi, dimineața cu un pahar de apă, pentru a maximiza rata de absorbție celulară de-a lungul zilei.", "question": "Care este doza recomandată?"}, {"answer": "Efectele de creștere a energiei se simt în 7-14 zile, însă refacerea celulară profundă necesită o cură de minimum 3 luni pentru rezultate optime.", "question": "În cât timp voi vedea efectele anti-aging?"}, {"answer": "Da, substanțele active sunt 100% bio-identice cu moleculele produse deja de corpul uman, fiind complet sigure și non-toxice.", "question": "Este sigur de administrat pe termen lung?"}], "reviews": [{"date": "10 Iulie 2026", "author": "Valeriu M.", "rating": 5, "comment": "Folosesc de 2 luni și am observat o îmbunătățire drastică a rezistenței la efort. Nu mai obosesc la fel de repede."}, {"date": "22 Iunie 2026", "author": "Simona T.", "rating": 5, "comment": "Analizele mele de sânge s-au îmbunătățit de când folosesc produsele voastre de longevitate. Recomand cu drag!"}, {"date": "05 Mai 2026", "author": "Andrei G.", "rating": 4, "comment": "Un supliment foarte bun. Prețul este corect pentru calitatea oferită."}], "banner_text": "Activează reînnoirea celulară și trăiește la potențialul maxim!", "content_image": "/images/premium_bottle_2-removebg-preview.png", "why_recommend": ["Puritate testată independent > 99%", "Formulă stabilizată pentru biodisponibilitate maximă", "Fără efecte adverse, sigur pentru utilizare zilnică", "Combate stresul oxidativ de la prima administrare"], "ingredients_table": [{"vnr": "**", "name": "Extract Purificat (99%)"