	('0b5a2b3e-9b7e-48df-96bf-eede56b9dbbb', NULL, 'Magneziu Bisglicinat', 'magneziu-bisglicinat', 75.00, '/images/premium_bottle_3-removebg-preview.png', false, '2026-08-04 09:46:15.360648+00', true, false, false, true, 'esentiale', 'Cea mai asimilabilă și blândă formă de magneziu (nu produce disconfort gastric). Combate stresul, relaxează musculatura și îmbunătățește masiv calitatea somnului.', 5.00, 534, '{"Super Preț"}', true, '{"faq": [{"answer": "Datorită formei sale de bisglicinat, este foarte blând cu stomacul și poate fi luat pe stomacul gol fără probleme, deși noi recomandăm seara după o masă ușoară.", "question": "Se poate lua pe stomacul gol?"}, {"answer": "Nu. Spre deosebire de oxidul sau citratul de magneziu, bisglicinatul se absoarbe direct și nu atrage apa în intestine, deci nu are niciun efect laxativ.", "question": "Are efect laxativ?"}], "reviews": [{"date": "14 August 2026", "author": "Andreea M.", "rating": 5, "comment": "Dorm mult mai adânc de când am început să îl iau. Mă trezesc odihnită și nu mai am deloc crampe musculare."}, {"date": "29 Iulie 2026", "author": "Florin B.", "rating": 5, "comment": "Cel mai bun magneziu pe care l-am încercat. Stomacul meu este foarte sensibil dar cu acesta nu am avut nicio problemă."}], "banner_text": "Somn profund, mușchi relaxați și sistem nervos echilibrat", "content_image": "/images/premium_bottle_3-removebg-preview.png", "why_recommend": ["Absorbție net superioară față de oxidul sau citratul de magneziu", "Bând cu stomacul, zero disconfort digestiv", "Sinergie cu Vitamina B6 bioactivă pentru relaxare musculară"], "ingredients_table": [{"vnr": "53%", "name": "Magneziu Elemental (din Bisglicinat)", "quantity": "200 mg"}, {"vnr": "142%", "name": "Vitamina B6 (Piridoxal-5-Fosfat)", "quantity": "2 mg"}, {"vnr": "**", "name": "L-Glicină liberă", "quantity": "100 mg"}, {"vnr": "-", "name": "Capsulă vegetală (HPMC)", "quantity": "-"}, {"vnr": "-", "name": "Făină de orez organică", "quantity": "-"}], "intro_description": "<p>Forma supremă de magneziu pentru calmarea sistemului nervos. Bisglicinatul de Magneziu este creat prin legarea magneziului de două molecule din aminoacidul Glicină, asigurând o absorbție intestinală excelentă <strong>fără efecte laxative</strong>.</p><p>Ideal pentru consum seara, înainte de culcare, acest supliment reduce stresul acumulat peste zi și pregătește corpul pentru un somn adânc, reparator.</p>"}', NULL),
